  Variables (lo : Z) (d : depot) (inited : bool).
  Variables (TSD CTX TH TOP BOT : Z) (CH : list (Z * Z)).
  Variable (sb : Z).
  Let CHI := icpt_chain (bv_unsigned ra) (bv_unsigned s0) (bv_unsigned sp) TOP CH.
  Let T := utrace 0x090c40 (bv_unsigned sp) TOP BOT 30 CHI.   (* [comment removed for export] *)
  (* [comment removed for export] *)
  Let W : list ivl := [(lo, bv_unsigned sp); (TH + 3168, TH + 3169); (2411528, 2411528 + 4); (1827712, 1827712 + 0x81030)].
