  Hypothesis LO : ltac2:(zQ "20!mnb!lv9@2$1@1$0?5HCEIL?2lo").  Hypothesis HI : ltac2:(zQ "40!h9!hu3!lv9!in5@2$2@2$1?2lo+ps0@2$3@1$0#k0?2sp").
  Hypothesis SPA : ltac2:(zQ "60!jl5!h9!k1!ms6!mt0!in5@1$3@3$0$2@2$4@2$5@1$1#k0?2sp+h0Z").
  Hypothesis SPT : ltac2:(zQ "60!h9!ms6!hu3!lv9!mgf!in5@1$1@2$3@2$2@2$5@1$0#k0?2sp+h0@2$4+2+if").
  Hypothesis P47 : ltac2:(zQ "40!h9!lvf!mgf!in5@2$1@2$3@1$0#k0?2a0@2$2+2+if").
  Hypothesis TPR : ltac2:(zQ "70!h9!lv9!in5!hs4!mta!ms6!hu3@1$5@2$3@2$1+mpvgs8@2$2@1$0#k0?2tp@2$1@2$6@2$2@1$0#k0?2tp+hgg0$4").
